    case.created_at = datetime.utcnow() - timedelta(days=age_days)
    session.commit()

    # the job is wrapped by the scheduler and timer decorators, call the raw function
    scheduled.case_close_reminder.__wrapped__.__wrapped__(db_session=session, project=case.project)

